import {ContractError,chinaDate,validDate} from './cloud-contract.mjs';
import {templateRecord,titleBatch} from './resource-model.mjs';
const fail=()=>{throw new ContractError('模板、标题或工具资料不完整，请重新核对。');};
const id=v=>{if(typeof v!=='string'||!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(v))fail();return v;};
const int=(v,min=0)=>{if(!Number.isSafeInteger(v)||v<min||v>2147483647)fail();return v;};
const text=(v,max,required=false)=>{if(typeof v!=='string'||v.length>max||required&&!v.trim())fail();return v.trim();};
export const libraryKind=k=>{if(!['template','titles','tool'].includes(k))fail();return k;};
export const libraryActions={create:'新建',edit:'编辑',rename:'重命名',append:'追加标题','edit-entry':'编辑标题','remove-entry':'移除未使用标题',archive:'归档',restore:'恢复'};
export function parseTitleRows(value){const lines=text(value,650000,true).split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(!lines.length||lines.length>1000)fail();return lines.map(line=>{const i=line.search(/[|｜\t]/);return {direction:text(i<0?'未分类':line.slice(0,i).trim()||'未分类',100,true),title:text(i<0?line:line.slice(i+1),500,true)};});}
function snapshot(kind,v){if(!v)fail();id(v.id);int(v.version,1);text(v.name,200,true);if(typeof v.archived!=='boolean')fail();if(kind==='template')templateRecord(v,true);else if(kind==='titles'){titleBatch(v);if(!validDate(v.batchDate)||v.items.length>1000)fail();for(const r of v.items){id(r.id);text(r.title,500,true);text(r.direction,100,true);int(r.usageCount);}}else{text(v.url,2048,true);text(v.category,60);text(v.description,2000);}return v;}
export function libraryState(v,kind,owner){if(!v||v.kind!==kind||v.current?.id!==owner||!v.history||!Array.isArray(v.history.rows)||v.history.rows.length>50||v.history.limit!==50)fail();libraryKind(kind);snapshot(kind,v.current);int(v.history.total);int(v.history.offset);for(const r of v.history.rows){id(r.id);if(!Object.hasOwn(libraryActions,r.action)||!Number.isFinite(Date.parse(r.createdAt)))fail();text(r.reason,2000,true);text(r.actor,100,true);}return v;}
export function libraryEvent(v,owner){if(!v||v.id!==owner||!Object.hasOwn(libraryActions,v.action)||!Number.isFinite(Date.parse(v.createdAt)))fail();id(v.id);id(v.targetId);libraryKind(v.kind);snapshot(v.kind,v.after);if(v.after.id!==v.targetId)fail();if(v.before!==null){snapshot(v.kind,v.before);if(v.before.id!==v.targetId)fail();}text(v.reason,2000,true);text(v.actor,100,true);return v;}
export function libraryPayload(kind,owner,b){libraryKind(kind);if(owner!==null)id(owner);if(!b||Object.keys(b).some(k=>!['requestKey','action','values','reason','entryId'].includes(k))||!Object.hasOwn(libraryActions,b.action)||!b.values||typeof b.values!=='object'||Array.isArray(b.values)||(owner===null)!==(b.action==='create'))fail();const action=b.action,v=b.values;let keys=[];
 if(['archive','restore','remove-entry'].includes(action))keys=[];
 else if(kind==='template'&&['create','edit'].includes(action))keys=['name','structure','product','scene','description','note','tags','rating','benchmarkUrl','sourceMaterialId','sourceExperimentId'];
 else if(kind==='tool'&&['create','edit'].includes(action))keys=['name','url','category','description'];
 else if(kind==='titles')keys=action==='create'?['name','batchDate','items']:action==='rename'?['name']:action==='append'?['items']:action==='edit-entry'?['title','direction']:null;
 else fail();if(!keys||kind!=='titles'&&['rename','append','edit-entry','remove-entry'].includes(action))fail();if(owner!==null)keys=[...keys,'expectedVersion'];if(keys.some(k=>!Object.hasOwn(v,k))||Object.keys(v).some(k=>!keys.includes(k)))fail();if(owner!==null)int(v.expectedVersion,1);
 if(v.name!==undefined)text(v.name,kind==='template'?200:100,true);if(v.structure!==undefined)text(v.structure,4000,true);for(const [k,max]of [['description',2000],['note',2000],['product',200],['scene',100],['category',60]])if(v[k]!==undefined)text(v[k],max);
 if(v.tags!==undefined&&(!Array.isArray(v.tags)||v.tags.length>30||v.tags.some(t=>typeof t!=='string'||!t.trim()||t.length>40)))fail();if(v.rating!==undefined&&v.rating!==null&&!['S','A','B','C'].includes(v.rating))fail();for(const k of ['sourceMaterialId','sourceExperimentId'])if(v[k]!==undefined&&v[k]!==null)id(v[k]);
 for(const k of ['url','benchmarkUrl'])if(v[k]){try{const u=new URL(v[k]);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||v[k].length>2048)fail();}catch{fail();}}
 if(v.batchDate!==undefined&&!validDate(v.batchDate))fail();if(v.items!==undefined){if(!Array.isArray(v.items)||!v.items.length||v.items.length>1000)fail();for(const r of v.items){text(r.title,500,true);text(r.direction,100,true);if(Object.keys(r).some(k=>!['title','direction'].includes(k)))fail();}}if(v.title!==undefined){text(v.title,500,true);text(v.direction,100,true);}const entryId=b.entryId??null;if(['edit-entry','remove-entry'].includes(action))id(entryId);else if(entryId!==null)fail();return {...b,requestKey:id(b.requestKey),entryId,reason:text(b.reason,2000,true)};
}
export function createLibraryEditors({api,h,mount,input,area,select}){
 async function libraryEdit(kind,owner=null,action='create',entryId=null){const s=owner?await api.libraryState(kind,owner):null,r=s?.current,key=crypto.randomUUID();if(r?.archived&&action!=='restore')throw new Error('请先恢复归档资料，再维护内容。');let body='',values;
  if(['archive','restore'].includes(action)){body=`<p class="planning-rule">${action==='archive'?'归档后从在用列表隐藏，保留原引用、发布与使用记录。':'恢复原记录，不复制内容，也不重置使用记录。'}</p>`;values=()=>({expectedVersion:r.version});}
  else if(kind==='template'){
   const [materials,experiments]=await Promise.all([api.materials(),api.experiments()]);const mOptions=[['','不关联'],...materials.filter(m=>!m.archived||m.id===r?.sourceMaterialId).map(m=>[m.id,m.title+(m.archived?'（已归档，原引用）':'')])],eOptions=[['','不关联'],...experiments.filter(e=>e.status==='concluded'||e.id===r?.sourceExperimentId).map(e=>[e.id,e.title])];
   body=input('name','模板名称',r?.name||'','required maxlength="200"')+area('structure','内容结构（必填）',r?.structure||'',4000)+input('product','适用产品',r?.product||'','maxlength="200"')+input('scene','适用场景',r?.scene||'','maxlength="100"')+area('description','使用说明',r?.description||'')+area('note','管理员备注',r?.note||'')+input('tags','标签（用逗号分开）',(r?.tags||[]).join('，'),'maxlength="1200"')+select('rating','管理员评级',r?.rating||'',[['','未评级'],...['S','A','B','C'].map(v=>[v,v])])+input('benchmarkUrl','参考链接',r?.benchmarkUrl||'','type="url" maxlength="2048"')+select('sourceMaterialId','来源素材',r?.sourceMaterialId||'',mOptions)+select('sourceExperimentId','已结束的来源实验',r?.sourceExperimentId||'',eOptions);
   values=f=>({name:f.get('name'),structure:f.get('structure'),product:f.get('product'),scene:f.get('scene'),description:f.get('description'),note:f.get('note'),tags:[...new Set(f.get('tags').split(/[,，\n]/).map(v=>v.trim()).filter(Boolean))],rating:f.get('rating')||null,benchmarkUrl:f.get('benchmarkUrl')||null,sourceMaterialId:f.get('sourceMaterialId')||null,sourceExperimentId:f.get('sourceExperimentId')||null,...(r?{expectedVersion:r.version}:{})});
  }else if(kind==='tool'){body=input('name','工具名称',r?.name||'','required maxlength="100"')+input('url','工具网址',r?.url||'','required type="url" maxlength="2048"')+input('category','分类',r?.category||'','maxlength="60"')+area('description','用途说明',r?.description||'');values=f=>({name:f.get('name'),url:f.get('url'),category:f.get('category'),description:f.get('description'),...(r?{expectedVersion:r.version}:{})});}
  else if(action==='create'||action==='append'){body=(action==='create'?input('name','标题批次名称','','required maxlength="100"')+input('batchDate','批次日期',chinaDate(),'required type="date"'):'')+area('items','每行一条：方向 | 标题（可只填写标题）','',650000)+'<p class="muted">每次最多1000条，批次总数最多1000条。维护不会增加复制、发布或使用次数。</p>';values=f=>({...(action==='create'?{name:f.get('name'),batchDate:f.get('batchDate')}:{expectedVersion:r.version}),items:parseTitleRows(f.get('items'))});}
  else if(action==='rename'){body=input('name','批次名称',r.name,'required maxlength="100"');values=f=>({name:f.get('name'),expectedVersion:r.version});}
  else{const e=r.items.find(e=>e.id===entryId);if(!e)throw new Error('标题暂不可见，请刷新。');if(action==='remove-entry'){if(e.usageCount>0)throw new Error('已记录使用的标题请保留，可编辑或归档批次。');body=`<p>移除未使用标题：${h(e.title)}</p><p class="muted">原批次和其他标题保留，本次变更留下前后历史。</p>`;values=()=>({expectedVersion:r.version});}else{body=input('title','标题内容',e.title,'required maxlength="500"')+input('direction','方向',e.direction,'required maxlength="100"')+'<p class="muted">保留原标题ID和已记录次数，不把编辑当作新的使用。</p>';values=f=>({title:f.get('title'),direction:f.get('direction'),expectedVersion:r.version});}}
  mount(libraryActions[action]+({template:'模板',titles:'标题资料',tool:'工具'}[kind]),(r?`<p>${h(r.name)} · 当前版本 ${r.version}</p>`:'')+body+area('reason','本次维护原因（必填）'),f=>api.saveLibrary(kind,owner,{requestKey:key,action,entryId,values:values(f),reason:f.get('reason')}),{kind:'library-maintenance',libraryKind:kind,id:owner},()=>api.libraryReceipt(kind,owner,key));
 }return {libraryEdit};
}
export function createLibraryViews({api,h,showPanel,localTime,notify,source}){
 const head=t=>`<div class="dialog-header"><h2>${h(t)}</h2><button class="icon-button" data-library-close aria-label="关闭维护历史">×</button></div>`;
 const content=(kind,v)=>!v?'<p class="muted">此前没有记录。</p>':`<p><b>${h(v.name)}</b> · 版本 ${v.version} · ${v.archived?'已归档':'在用'}</p>`+(kind==='template'?`<h4>内容结构</h4><p class="preserve-text">${h(v.structure)}</p><p>产品：${h(v.product||'未填写')} · 场景：${h(v.scene||'未填写')} · 评级：${h(v.rating||'未评级')}</p><p class="preserve-text">${h(v.description||'')}</p><p class="preserve-text">${h(v.note||'')}</p><p>${h(v.tags.join('、'))}</p>`:kind==='tool'?`${source(v.url)}<p>${h(v.category||'未分类')}</p><p class="preserve-text">${h(v.description||'')}</p>`:`<p>批次日期 ${h(v.batchDate)} · ${v.items.length} 条</p>${v.items.map(e=>`<article class="observation"><span>${h(e.direction)}</span><p>${h(e.title)}</p><small>当时已记录 ${e.usageCount} 次</small></article>`).join('')}`);
 async function history(kind,owner,offset=0){await showPanel('维护历史',async signal=>{const s=await api.libraryState(kind,owner,offset,signal);return head(s.current.name+' · 维护历史')+`<p class="muted">查看每次维护的原因和当时内容。历史从启用维护功能后开始记录。</p>${s.history.rows.map(e=>`<article class="observation"><button class="text-button" data-library-event="${h(e.id)}">${h(libraryActions[e.action])} · 查看当时内容</button><p class="preserve-text">${h(e.reason)}</p><small>${h(e.actor)} · ${h(localTime(e.createdAt))}</small></article>`).join('')||'<p class="muted">尚无维护记录。</p>'}<div class="pager"><button class="secondary" data-library-history="${kind}" data-id="${h(owner)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${s.history.total} 条</span><button class="secondary" data-library-history="${kind}" data-id="${h(owner)}" data-offset="${offset+50}" ${offset+50>=s.history.total?'disabled':''}>下一页</button></div>`;});}
 async function event(id){await showPanel('当时内容与修改依据',async signal=>{const e=await api.libraryEvent(id,signal);return head(libraryActions[e.action]+' · 当时内容')+`<button class="text-button" data-library-history="${e.kind}" data-id="${h(e.targetId)}">返回维护历史</button><p class="preserve-text">${h(e.reason)}</p><p>${h(e.actor)} · ${h(localTime(e.createdAt))}</p><h3>变更前</h3>${content(e.kind,e.before)}<h3>变更后</h3>${content(e.kind,e.after)}`;});}
 document.addEventListener('click',e=>{if(e.target.closest('[data-library-close]'))document.querySelector('#cloud-detail').close();const b=e.target.closest('[data-library-history]'),r=e.target.closest('[data-library-event]');if(b)history(b.dataset.libraryHistory,b.dataset.id,Number(b.dataset.offset||0)).catch(e=>notify(e.message));if(r)event(r.dataset.libraryEvent).catch(e=>notify(e.message));});return {history,event};
}
